const seriesData = context.panel.data.series[0];
const fields = seriesData.fields;

function getField(name) {
  return fields.find((f) => f.name === name);
}

function valuesOf(name) {
  const f = getField(name);
  if (!f) {
    return [];
  }
  return Array.from(f.values.buffer || f.values);
}

const starts = valuesOf('start_time');
const ends = valuesOf('end_time');
const airtimes = valuesOf('airtime_ms');
const types = valuesOf('payload_type');
const routeTypes = valuesOf('payload_route_type');

function routeGroup(rt) {
  rt = String(rt);

  if (rt === '0' || rt === '3') return 'mit Region';
  if (rt === '1') return 'ohne Region';
  if (rt === '2') return 'mit Pfad';

  return 'unbekannt';
}

function routeColor(rt) {
  const g = routeGroup(rt);

  if (g === 'mit Region') return '#2196f3'; // blau
  if (g === 'ohne Region') return '#f44336'; // rot
  if (g === 'mit Pfad') return '#ffeb3b'; // gelb

  return '#9e9e9e';
}

const chartData = starts.map((start, i) => {
  const rt = routeTypes[i];

  return {
    name: routeGroup(rt),
    value: [
      0,
      new Date(start).getTime(),
      new Date(ends[i]).getTime(),
      Number(airtimes[i]),
      types[i],
      routeGroup(rt),
      String(rt),
    ],
    itemStyle: {
      color: routeColor(rt),
    },
  };
});

function renderItem(params, api) {
  const categoryIndex = api.value(0);
  const start = api.coord([api.value(1), categoryIndex]);
  const end = api.coord([api.value(2), categoryIndex]);

  const height = api.size([0, 1])[1] * 0.65;

  const rectShape = context.echarts.graphic.clipRectByRect(
    {
      x: start[0],
      y: start[1] - height / 2,
      width: Math.max(end[0] - start[0], 1),
      height: height,
    },
    {
      x: params.coordSys.x,
      y: params.coordSys.y,
      width: params.coordSys.width,
      height: params.coordSys.height,
    }
  );

  return (
    rectShape && {
      type: 'rect',
      shape: rectShape,
      style: api.style(),
    }
  );
}

return {
  backgroundColor: 'transparent',
  tooltip: {
    formatter: function (params) {
      const start = new Date(params.value[1]).toLocaleString();
      const end = new Date(params.value[2]).toLocaleString();
      const airtime = params.value[3];

      return `
        <b>${params.value[5]}</b><br/>
        Route-Type: ${params.value[6]}<br/>
        Pakettyp: ${params.value[4]}<br/>
        Start: ${start}<br/>
        Ende: ${end}<br/>
        Airtime: ${airtime.toFixed(1)} ms
      `;
    },
  },
  legend: {
    bottom: 0,
    data: ['mit Region', 'ohne Region', 'mit Pfad'],
  },
  grid: {
    left: 80,
    right: 20,
    top: 20,
    bottom: 50,
  },
  xAxis: {
    type: 'time',
  },
  yAxis: {
    type: 'category',
    data: ['Frequenz'],
  },
  series: [
    {
      type: 'custom',
      renderItem: renderItem,
      encode: {
        x: [1, 2],
        y: 0,
      },
      data: chartData,
    },
  ],
};

