options.getOption:
const seriesData = context.panel.data.series[0];
const fields = seriesData.fields;

function valuesOf(name) {
  const f = fields.find((f) => f.name === name);
  if (!f) return [];
  return Array.from(f.values.buffer || f.values);
}

const starts = valuesOf('start_time');
const ends = valuesOf('end_time');
const airtimes = valuesOf('airtime_ms');
const types = valuesOf('payload_type');
const repeaters = valuesOf('repeater');
const routeTypes = valuesOf('payload_route_type');
const hashes = valuesOf('packet_payload_sha256');

const categories = [...new Set(repeaters)].sort();

function group(rt) {
  rt = String(rt);

  if (rt === '0' || rt === '3') return 'mit Region';
  if (rt === '1') return 'ohne Region';
  if (rt === '2') return 'mit Pfad';

  return 'unbekannt';
}

function colorForGroup(g) {
  if (g === 'mit Region') return '#2196f3';
  if (g === 'ohne Region') return '#f44336';
  if (g === 'mit Pfad') return '#ffeb3b';

  return '#9e9e9e';
}

const allData = starts.map((start, i) => {
  const repeater = repeaters[i];
  const g = group(routeTypes[i]);

  return {
    group: g,
    value: [
      categories.indexOf(repeater),
      new Date(start).getTime(),
      new Date(ends[i]).getTime(),
      Number(airtimes[i]),
      types[i],
      repeater,
      g,
      String(routeTypes[i]),
      hashes[i],
    ],
  };
});

function renderItem(params, api) {
  const categoryIndex = api.value(0);
  const start = api.coord([api.value(1), categoryIndex]);
  const end = api.coord([api.value(2), categoryIndex]);
  const height = api.size([0, 1])[1] * 0.6;

  const rectShape = context.echarts.graphic.clipRectByRect(
    {
      x: start[0],
      y: start[1] - height / 2,
      width: Math.max(end[0] - start[0], 1),
      height: height,
    },
    {
      x: params.coordSys.x,
      y: params.coordSys.y,
      width: params.coordSys.width,
      height: params.coordSys.height,
    }
  );

  return rectShape && {
    type: 'rect',
    shape: rectShape,
    style: api.style(),
  };
}

function makeSeries(groupName) {
  return {
    name: groupName,
    type: 'custom',
    renderItem,
    silent: false,
    itemStyle: {
      color: colorForGroup(groupName),
    },
    encode: {
      x: [1, 2],
      y: 0,
    },
    data: allData.filter((d) => d.group === groupName),
  };
}

setTimeout(() => {
  context.panel.chart.off('click');

  context.panel.chart.on('click', function (params) {
    if (!params.value || !params.value[8]) return;

    const hash = params.value[8];

    locationService.push(
      `/d/adtsdcx/meshcore-paket-analyse?var-hash=${hash}`
    );
  });
}, 300);

return {
  backgroundColor: 'transparent',
  tooltip: {
    formatter: function (params) {
      return `
        <b>${params.value[6]}</b><br/>
        Route-Type: ${params.value[7]}<br/>
        Pakettyp: ${params.value[4]}<br/>
        Repeater: ${params.value[5]}<br/>
        Hash: ${params.value[8]}<br/>
        Start: ${new Date(params.value[1]).toLocaleString()}<br/>
        Ende: ${new Date(params.value[2]).toLocaleString()}<br/>
        Airtime: ${params.value[3].toFixed(1)} ms<br/>
        <br/>
        Klick öffnet Paket-Analyse
      `;
    },
  },
  legend: {
    bottom: 0,
    data: ['mit Region', 'ohne Region', 'mit Pfad'],
    textStyle: {
      color: '#ccc',
    },
  },
  grid: {
    left: 80,
    right: 20,
    top: 20,
    bottom: 50,
  },
  xAxis: {
    type: 'time',
  },
  yAxis: {
    type: 'category',
    data: categories,
  },
  series: [
    makeSeries('mit Region'),
    makeSeries('ohne Region'),
    makeSeries('mit Pfad'),
  ],
};

